import collections

def maxSubstringLength(s: str, k: int) -> bool:
    if k == 0:
        return True

    n = len(s)
    # Pre-calculate first and last occurrences of each character
    first_occ = {}
    last_occ = {}
    for idx, char in enumerate(s):
        if char not in first_occ:
            first_occ[char] = idx
        last_occ[char] = idx

    # A substring s[i:j+1] is special if:
    # 1. For every character c at index p (i <= p <= j), first_occ[c] >= i and last_occ[c] <= j.
    # 2. The range [i, j] is not the entire string s (0 < len(s[i:j+1]) < n).

    intervals = []
    for i in range(n):
        curr_max_last = -1
        visited_chars = set()
        # Optimization: if we already passed a point where the char's first occurrence 
        # is before i, no special substring can start at or after this.
        # However, for simplicity and correctness with n=5*10^4, we need to be careful.
        # Let's check if s[i] belongs to a character that appeared before i.
        if first_occ[s[i]] < i:
            continue

        for j in range(i, n):
            char = s[j]
            if char not in visited_chars:
                visited_chars.add(char)
                curr_max_last = max(curr_max_last, last_occ[char])

            # If the current character's first occurrence is before our start i, 
            # this substring s[i:j+1] can never be special for any j >= current j.
            if first_occ[char] < i:
                break

            if curr_max_last == j:
                # Check if it's not the whole string
                if j + 1 < n:
                    intervals.append((j + 1, i))
                    break

    # Greedy interval scheduling: sort by end time
    intervals.sort()
    count = 0
    last_end = -1
    for end, start in intervals:
        if start >= last_end:
            count += 1
            last_end = end

    return count >= k

