import collections
import bisect
from typing import List

def maxSubarrays(n: int, conflictingPairs: List[List[int]]) -> int:
    pairs = []
    for u, v in conflictingPairs:
        if u > v:
            u, v = v, u
        pairs.append((u, v))

    adj = [[] for _ in range(n + 1)]
    for a, b in pairs:
        adj[a].append(b)
    for a in range(1, n + 1):
        adj[a].sort()

    m1 = [0] * (n + 2)
    m2 = [0] * (n + 2)
    cnt1 = [0] * (n + 2)
    cur_m1, cur_m2, cur_cnt1 = n + 1, n + 2, 0
    for i in range(n, 0, -1):
        if adj[i]:
            for b in adj[i]:
                if b < cur_m1:
                    cur_m2 = cur_m1
                    cur_m1 = b
                    cur_cnt1 = 1
                elif b == cur_m1:
                    cur_cnt1 += 1
                elif b < cur_m2:
                    cur_m2 = b
        m1[i] = cur_m1
        m2[i] = cur_m2
        cnt1[i] = cur_cnt1

    base_total = 0
    for i in range(1, n + 1):
        base_total += max(0, m1[i] - i)

    L_with_idx = collections.defaultdict(list)
    for idx, (a, b) in enumerate(pairs):
        if b == adj[a][0]:
            L_with_idx[b].append((a, idx))

    for b in L_with_idx:
        L_with_idx[b].sort()

    gains = [0] * len(pairs)
    for i in range(1, n + 1):
        if cnt1[i] == 1 and m1[i] != n + 1:
            b = m1[i]
            target_list = L_with_idx[b]
            pos = bisect.bisect_left(target_list, (i, -1))
            if pos < len(target_list):
                _, pair_idx = target_list[pos]
                gains[pair_idx] += (m2[i] - m1[i])

    return base_total + max(gains) if gains else base_total
