from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[sum] = set of products
    # We need to track two states because the sign depends on whether 
    # the next element will be at an even or odd position in the subsequence.
    # state_even: last element added was at an ODD index (so next is EVEN, we ADD)
    # state_odd: last element added was at an EVEN index (so next is ODD, we SUBTRACT)
    # Initial state: We can start a subsequence with any nums[i] as the 0-th (even) index.

    # dp[current_sum][is_next_even] = set of products
    # is_next_even: True if next element to be added will be at an even index (add it),
    #                False if next element to be added will be at an odd index (subtract it).
    dp = {} # Key: (current_sum, is_next_even), Value: set of products

    for x in nums:
        new_dp = dp.copy()

        # Option 1: Start a new subsequence with x as the 0-th index (Even position)
        # Alternating sum = +x, Next will be odd (-).
        s1 = x
        p1 = x
        if p1 <= limit:
            state1 = (s1, False)
            if state1 not in new_dp: new_dp[state1] = set()
            new_dp[state1].add(p1)

        # Option 2: Append x to existing subsequences
        for (curr_sum, is_next_even), products in dp.items():
            if is_next_even: # Next index is even, so add x
                new_sum = curr_sum + x
                for p in products:
                    new_prod = p * x
                    if new_prod <= limit:
                        state = (new_sum, False)
                        if state not in new_dp: new_dp[state] = set()
                        new_dp[state].add(new_prod)
            else: # Next index is odd, so subtract x
                new_sum = curr_sum - x
                for p in products:
                    new_prod = p * x
                    if new_prod <= limit:
                        state = (new_sum, True)
                        if state not in new_dp: new_dp[state] = set()
                        new_dp[state].add(new_prod)

        # To optimize memory and time, we update dp. 
        # Since we can't easily iterate and update the same dict, 
        # we use a temp dict for new additions at this step.
        # However, the logic above handles "starting new" or "extending".
        # Let's refine the iteration to avoid using updated values in the same loop.

    # The logic above needs careful handling of updates. 
    # Let's rewrite it more cleanly:

    current_states = {} # (sum, is_next_even) -> set of products

    for x in nums:
        next_states = current_states.copy()

        # Try starting a new subsequence with x at index 0 (Even position)
        s_start = x
        p_start = x
        if p_start <= limit:
            state_start = (s_start, False)
            next_states[state_start] = next_states.get(state_start, set()) | {p_start}

        for (curr_sum, is_next_even), products in current_states.items():
            if is_next_even: # Add x to even position
                new_s = curr_sum + x
                new_state = (new_s, False)
                for p in products:
                    new_p = p * x
                    if new_p <= limit:
                        next_states[new_state] = next_states.get(new_state, set()) | {new_p}
            else: # Subtract x from odd position
                new_s = curr_sum - x
                new_state = (new_s, True)
                for p in products:
                    new_p = p * x
                    if new_p <= limit:
                        next_states[new_state] = next_states.get(new_state, set()) | {new_p}
        current_states = next_states

    max_prod = -1
    for (curr_sum, is_next_even), products in current_states.items():
        if curr_sum == k:
            for p in products:
                if p > max_prod:
                    max_prod = p

    return max_prod

