    total_area = 0
    sq_data = []
    for x, y, l in squares:
        total_area += l * l
        sq_data.append((y, l))

    target = total_area / 2.0

    # Find global bounds for y
    low = 0.0
    high = 0.0
    for y, l in sq_data:
        if y < low: low = float(y)
        if y + l > high: high = float(y + l)

    # Binary search for the y coordinate
    # Using 100 iterations to ensure precision for 10^-5 requirement
    for _ in range(100):
        mid = (low + high) / 2
        current_area = 0.0
        for y, l in sq_data:
            bottom = float(y)
            top = bottom + l
            if mid > bottom:
                height = min(mid, top) - bottom
                current_area += height * l

        if current_area < target:
            low = mid
        else:
            high = mid

    return low
